use mip_codex::{revised::{Problem,minimize_warm},lp::Outcome};
use serde::Deserialize;
use std::time::{Instant,Duration};
#[derive(Deserialize)]struct Saved{problem:SavedProblem}
#[derive(Deserialize)]struct SavedProblem{columns:Vec<Vec<(usize,f64)>>,rhs:Vec<f64>,costs:Vec<f64>,upper:Vec<Option<f64>>,equality:Vec<bool>,slack_upper:Vec<Option<f64>>}
fn main(){let a:Vec<_>=std::env::args().collect();let saved:Saved=serde_json::from_slice(&std::fs::read(&a[1]).unwrap()).unwrap();let p=saved.problem;let p=Problem{columns:p.columns,rhs:p.rhs,costs:p.costs,upper:p.upper.into_iter().map(|v|v.unwrap_or(f64::INFINITY)).collect(),equality:p.equality,slack_upper:p.slack_upper.into_iter().map(|v|v.unwrap_or(f64::INFINITY)).collect()};let start=Instant::now();let seconds:f64=a[2].parse().unwrap();let r=minimize_warm(&p,usize::MAX,Some(start+Duration::from_secs_f64(seconds)),None);let(status,objective,point)=match r.outcome{Outcome::Optimal{objective,x}=>("optimal",Some(objective),Some(x)),Outcome::Infeasible=>("infeasible",None,None),Outcome::Unbounded=>("unbounded",None,None),Outcome::TimeLimit=>("time_limit",None,None),Outcome::IterationLimit=>("iteration_limit",None,None),Outcome::NumericalError=>("numerical_error",None,None)};println!("{}",serde_json::json!({"status":status,"objective":objective,"dual_bound":r.dual,"point":point,"seconds":start.elapsed().as_secs_f64(),"pivots":r.stats.pivots,"flips":r.stats.flips,"cold_recovery_attempts":r.stats.cold_recovery_attempts,"cold_recovery_candidates":r.stats.cold_recovery_candidates,"base_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"purpose":"isolated saved LP diagnostic; no original-MIP feasibility or optimality claim"}));}
